def check(args, got):
    from collections import Counter
    s, t = args
    if not isinstance(got, str):
        return False
    need = Counter(t)
    # shortest covering length via sliding window
    have, formed, left, best = Counter(), 0, 0, None
    for right, ch in enumerate(s):
        have[ch] += 1
        if ch in need and have[ch] == need[ch]:
            formed += 1
        while formed == len(need) and left <= right:
            if best is None or right - left + 1 < best:
                best = right - left + 1
            lc = s[left]
            have[lc] -= 1
            if lc in need and have[lc] < need[lc]:
                formed -= 1
            left += 1
    if best is None:
        return got == ""
    if len(got) != best or got not in s:
        return False
    cnt = Counter(got)
    return all(cnt[c] >= k for c, k in need.items())
